  ('CM-R5', 1, 'CODE-LOOP-EXHAUSTED-1', 'replacement-merged', 'sql', 'WITH e AS (SELECT a.id AS issue_id, t.id AS task_id, t.status AS tstatus, t.step AS step, t.attempts AS attempts, t.created_at AS tcreated, CASE WHEN t.goal LIKE ''[issue #%'' THEN CAST(substr(t.goal, 9, instr(t.goal, '']'') - 9) AS INTEGER) WHEN t.id LIKE ''ct_im%'' THEN CAST(substr(t.id, 6) AS INTEGER) END AS parent_id FROM agent_issues a JOIN code_tasks t ON t.id = substr(a.title, 24, instr(substr(a.title, 24) || '' '', '' '') - 1) WHERE a.status = ''open'' AND a.title LIKE ''CODE-LOOP-EXHAUSTED-1: ct_% %''), sib AS (SELECT e.issue_id AS issue_id, s.id AS sid, s.path AS spath, s.pr_url AS spr, s.merged_at AS smerged, s.merged_sha AS ssha, l2.pr_number AS spr_number, MAX(s.merged_at) AS _latest FROM e JOIN code_tasks s ON s.id <> e.task_id AND s.status = ''merged'' AND s.merged_at IS NOT NULL AND s.merged_sha IS NOT NULL AND (s.id = ''ct_im'' || e.parent_id OR s.goal LIKE ''[issue #'' || e.parent_id || '']%'' OR s.goal LIKE ''%-- issue #'' || e.parent_id || '' (RED-DRAIN-1%'') LEFT JOIN code_task_pr_links l2 ON l2.task_id = s.id WHERE e.parent_id IS NOT NULL AND datetime(s.merged_at) >= datetime(e.tcreated) GROUP BY e.issue_id) SELECT e.issue_id AS issue_id, ''replacement-merged'' AS subject, json_object(''task_id'', e.task_id, ''parent_id'', e.parent_id, ''sibling_task'', sib.sid, ''sibling_merged_at'', sib.smerged, ''sibling_sha7'', substr(sib.ssha, 1, 7)) AS facts_json FROM e JOIN sib ON sib.issue_id = e.issue_id JOIN agent_issues a ON a.id = e.issue_id WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'') AND COALESCE(c.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims w WHERE (w.issue_id = a.id OR w.path = ''issue:'' || a.id) AND w.released_at IS NULL AND w.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''))', json_array('WITH e AS (SELECT a.id AS issue_id, t.id AS task_id, t.status AS tstatus, t.step AS step, t.attempts AS attempts, t.created_at AS tcreated, CASE WHEN t.goal LIKE ''[issue #%'' THEN CAST(substr(t.goal, 9, instr(t.goal, '']'') - 9) AS INTEGER) WHEN t.id LIKE ''ct_im%'' THEN CAST(substr(t.id, 6) AS INTEGER) END AS parent_id FROM agent_issues a JOIN code_tasks t ON t.id = substr(a.title, 24, instr(substr(a.title, 24) || '' '', '' '') - 1) WHERE a.status = ''open'' AND a.title LIKE ''CODE-LOOP-EXHAUSTED-1: ct_% %''), sib AS (SELECT e.issue_id AS issue_id, s.id AS sid, s.path AS spath, s.pr_url AS spr, s.merged_at AS smerged, s.merged_sha AS ssha, l2.pr_number AS spr_number, MAX(s.merged_at) AS _latest FROM e JOIN code_tasks s ON s.id <> e.task_id AND s.status = ''merged'' AND s.merged_at IS NOT NULL AND s.merged_sha IS NOT NULL AND (s.id = ''ct_im'' || e.parent_id OR s.goal LIKE ''[issue #'' || e.parent_id || '']%'' OR s.goal LIKE ''%-- issue #'' || e.parent_id || '' (RED-DRAIN-1%'') LEFT JOIN code_task_pr_links l2 ON l2.task_id = s.id WHERE e.parent_id IS NOT NULL AND datetime(s.merged_at) >= datetime(e.tcreated) GROUP BY e.issue_id) INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT a.id, ''breach-doctor:CM-R5'', ''closed'', ''breach-doctor'', datetime(''now''), ''DoD met by a replacement task: '' || sib.sid || '' (same source issue #'' || e.parent_id || '', path '' || sib.spath || '') reached merged ('' || COALESCE(''PR #'' || sib.spr_number, ''PR '' || COALESCE(sib.spr, ''?'')) || '' at '' || sib.smerged || '', merge sha '' || substr(sib.ssha, 1, 7) || '') after '' || e.task_id || '' began, so '' || e.task_id || '' was a superseded retry. The source issue #'' || e.parent_id || '' stays open on its own contract. Closed by breach-doctor rule CM-R5 from code_tasks and code_task_pr_links facts only.'' FROM e JOIN sib ON sib.issue_id = e.issue_id JOIN agent_issues a ON a.id = e.issue_id WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'') AND COALESCE(c.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims w WHERE (w.issue_id = a.id OR w.path = ''issue:'' || a.id) AND w.released_at IS NULL AND w.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND a.id = ?1 ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = ''closed'', owner = ''breach-doctor'', close_evidence = excluded.close_evidence'), json_array('UPDATE issue_triage SET triage_state = ''triaged'', close_evidence = NULL WHERE issue_id = ?1', 'UPDATE agent_issues SET status = ''open'', close_channel = NULL, updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE id = ?1 AND status = ''closed'''), 'WITH e AS (SELECT a.id AS issue_id, t.id AS task_id, t.status AS tstatus, t.step AS step, t.attempts AS attempts, t.created_at AS tcreated, CASE WHEN t.goal LIKE ''[issue #%'' THEN CAST(substr(t.goal, 9, instr(t.goal, '']'') - 9) AS INTEGER) WHEN t.id LIKE ''ct_im%'' THEN CAST(substr(t.id, 6) AS INTEGER) END AS parent_id FROM agent_issues a JOIN code_tasks t ON t.id = substr(a.title, 24, instr(substr(a.title, 24) || '' '', '' '') - 1) WHERE a.title LIKE ''CODE-LOOP-EXHAUSTED-1: ct_% %''), sib AS (SELECT e.issue_id AS issue_id, s.id AS sid, s.path AS spath, s.pr_url AS spr, s.merged_at AS smerged, s.merged_sha AS ssha, l2.pr_number AS spr_number, MAX(s.merged_at) AS _latest FROM e JOIN code_tasks s ON s.id <> e.task_id AND s.status = ''merged'' AND s.merged_at IS NOT NULL AND s.merged_sha IS NOT NULL AND (s.id = ''ct_im'' || e.parent_id OR s.goal LIKE ''[issue #'' || e.parent_id || '']%'' OR s.goal LIKE ''%-- issue #'' || e.parent_id || '' (RED-DRAIN-1%'') LEFT JOIN code_task_pr_links l2 ON l2.task_id = s.id WHERE e.parent_id IS NOT NULL AND datetime(s.merged_at) >= datetime(e.tcreated) GROUP BY e.issue_id) SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status IN (''closed'',''resolved'')) THEN ''issue-reopened'' WHEN EXISTS (SELECT 1 FROM sib WHERE sib.issue_id = ?1) THEN ''ok'' ELSE ''sibling-not-merged'' END AS observed', 'delegated', 6, 20, 1, 'on', 'The exhausted task has a sibling for the same source issue that reached merged after it began (2 open on 2026-10-26 06:36Z). The source issue stays open on its own contract. issue-meta-fold closed them at 06:51Z: this rule is the 10-minute second path.'),
  ('playbook-gap', 1, '*', 'unclassified', 'file-issue', 'SELECT NULL AS issue_id, d.family AS subject, json_object(''unclassified_cases'', COUNT(*)) AS facts_json FROM v_breach_diagnosis_current d WHERE d.state = ''diagnosed'' AND d.cause_class = ''unclassified'' GROUP BY d.family', '[]', '[]', 'SELECT ''closed'' AS expected, COALESCE((SELECT status FROM agent_issues WHERE id = ?1), ''missing'') AS observed', 'delegated', 3, 24, 1, 'measure', 'Not a per-issue rule: the engine reads this row for the switch, mode and cap of the family-level issue ''BREACH-DOCTOR-1: playbook gap <family>'' (at most one per family per 24 hours, never for OWNER-CHAT, OWNER-REQUEST or other, none while 3 are open). Seeded in MEASURE and files nothing: a gap issue carries no code-task or code-anchor line the code loop can edit (the lever is a new playbook row by migration), so it would only add an unowned issue (control breach-doctor-gap-measure). The gap is recorded by family in breach_diagnoses (cause_class unclassified) and in v_breach_doctor_status.gap_by_family. To turn gap filing on: UPDATE breach_playbooks SET mode = ''on'' WHERE rule_id = ''playbook-gap'', by migration. A new family gets its own playbook row by migration.');

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, last_value, last_refreshed, state, refresh_class) VALUES
 ('breaches_undiagnosed_over_60m', 'operational', 'target', 'open issues older than breach_doctor_min_age_min + 60 minutes (180 by default) with no doer (code-task line, live code task, live work claim) and no breach_diagnoses row whose cause was found (diagnosed_at set and cause_class other than unclassified). An issue classified unclassified was looked at and matched no playbook: that is classification coverage, not a cause, so it stays counted until a playbook finds its cause or it gets a doer or closes. Issues titled BREACH-DOCTOR-1: are counted like any other. Written by the doctor tick, never by a D1 trigger',
  'qnfo-audit.breach_diagnoses (BREACH-DOCTOR-1)', '417 old open issues, none diagnosed, 2026-10-26', '0', 'qnfo-fleet-control', 'trigger gt 0', '*/10', '> 0', '> 60', NULL, NULL, 'MEASURED', 'computed'),
 ('breaches_auto_remediated_24h', 'outcome', 'target', 'breach_diagnoses rows that reached state verified in the last 24 hours (two consecutive verify passes after the action)',
  'qnfo-audit.breach_diagnoses (BREACH-DOCTOR-1)', '0 on 2026-10-26', '>= 12 (1.5 x the 8 unowned issues opened a day, ISSUE-THROUGHPUT-1)', 'qnfo-fleet-control', 'trigger lt 12', '*/10', '< 12', '< 4', NULL, NULL, 'MEASURED', 'computed'),
 ('doctor_actions_failed_24h', 'operational', 'guard', 'doctor cases that ended failed or reverted in the last 24 hours (failed verify, SQL error, expired lease, an action that changed no row)',
  'qnfo-audit.breach_diagnoses (BREACH-DOCTOR-1)', '0', '0', 'qnfo-fleet-control', 'trigger gt 0', '*/10', '> 0', '> 3', NULL, NULL, 'MEASURED', 'computed'),
 ('doctor_tick_age_min', 'operational', 'target', 'minutes between the previous doctor tick event and this one, written by the tick itself; fm-breach-doctor-stalled reads the events directly, so a dead doctor cannot hide behind its own metric',
  'qnfo-audit.breach_diagnosis_events (BREACH-DOCTOR-1)', 'n/a', '<= 15', 'qnfo-fleet-control', 'trigger gt 30', '*/10', '> 15', '> 30', NULL, NULL, 'MEASURED', 'computed'),
 ('doctor_taint_violations_24h', 'operational', 'guard', 'playbooks or fact values the doctor dropped in the last 24 hours because they were not a playbook constant, a number, an id or an enum code (taint-drop events); above 0 means a playbook is copying free text',
  'qnfo-audit.breach_diagnosis_events (BREACH-DOCTOR-1)', '0', '0', 'qnfo-fleet-control', 'trigger gt 0', '*/10', '> 0', '> 0', NULL, NULL, 'MEASURED', 'computed');

-- BREACH-ONE-MEANING-1 (migrations/2026-10-26-breach-one-meaning.sql, applied 08:44Z) reads a metric in breach that has no metric_breach_cause row as cause 'unmapped', counts it in
-- breaches_unmapped (target 0) and watches it with the detector fm-breach-unmapped. Two doctor metrics breach on the first tick (breaches_undiagnosed_over_60m, breaches_auto_remediated_24h), so
-- this file maps all five in the same change, the way BREACH-ONE-MEANING-2 maps the metrics it registers (a mapping left to a later issue is a new breach the fleet filed against itself).
-- The two tables are created here with the live column lists (IF NOT EXISTS: a no-op on qnfo-audit, where BREACH-ONE-MEANING-1 made them; migrations apply in file-name order and this name sorts first).
-- INSERT OR IGNORE: a mapping a later migration changed is not overwritten on a replay.
CREATE TABLE IF NOT EXISTS breach_causes (
  cause_key TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  plain TEXT NOT NULL,
  lever TEXT NOT NULL,
  doer TEXT NOT NULL,
  needs_owner INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);
CREATE TABLE IF NOT EXISTS metric_breach_cause (
  metric_key TEXT PRIMARY KEY,
  cause_key TEXT NOT NULL,
  note TEXT
);
INSERT OR IGNORE INTO breach_causes (cause_key, title, plain, lever, doer, needs_owner) VALUES
 ('breach-doctor', 'The breach doctor''s own playbooks misfire',
  'A rule the breach doctor runs failed its verify, changed no row, or carried a value that is not an id, a number or an enum code. After two failures in 24 hours the rule demotes itself to measure, so it changes nothing further until its row is fixed.',
  'Fix the breach_playbooks row named by rule_id by migration (its action_sql guard or its verify_sql) and set it back to on; after three failures on one issue the doctor files BREACH-DOCTOR-1: self <rule> <code> once.',
  'qnfo-fleet-control (breach doctor)', 0);
INSERT OR IGNORE INTO metric_breach_cause (metric_key, cause_key, note) VALUES
 ('breaches_undiagnosed_over_60m', 'issue-backlog', 'BREACH-DOCTOR-1'),
 ('breaches_auto_remediated_24h', 'issue-backlog', 'BREACH-DOCTOR-1'),
 ('doctor_tick_age_min', 'heartbeat', 'BREACH-DOCTOR-1'),
 ('doctor_actions_failed_24h', 'breach-doctor', 'BREACH-DOCTOR-1'),
 ('doctor_taint_violations_24h', 'breach-doctor', 'BREACH-DOCTOR-1');

-- No trigger action below carries a code-task or code-anchor line (review 2026-10-26, ACT-BRIDGE-1): that bridge is for a remedy that is one named edit in one file. The levers of these five
-- metrics are ops_config switches, a breach_playbooks row by migration, or waiting; the one edit that could make "undiagnosed > 0" read 0 is to the engine's own metric (a Goodhart move),
-- and breaches_undiagnosed_over_60m clears itself as the engine drains the backlog. Pointing the trusted auto-merge lane at the engine for that would be a task with no stated edit.
INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'breaches_undiagnosed_over_60m', 'Open issues with no doer wait without a diagnosis', 'registry', 'gt', 0, 1,
  'Pillar autonomy (owner, 2026-10-24: the fleet must diagnose and remediate its own breaches). Read: SELECT * FROM v_breach_doctor_status; SELECT event, detail, ts FROM breach_diagnosis_events WHERE event IN (''tick'', ''budget-skip'', ''taint-drop'') ORDER BY id DESC LIMIT 30; SELECT family, cause_class, COUNT(*) FROM v_breach_diagnosis_current GROUP BY 1, 2. An issue the doctor classified unclassified is still counted: the cause is not found until a playbook matches it. Levers: the tick is not running (see doctor_tick_age_min), breach_doctor is off or measure (ops_config), breach_doctor_max_cases / breach_doctor_budget_ms are too small for the backlog (raise by migration with its note), or the largest family has no playbook (SELECT family, COUNT(*) FROM v_breach_diagnosis_current WHERE cause_class = ''unclassified'' GROUP BY 1 ORDER BY 2 DESC; add a breach_playbooks row for it by migration, see the shape in migrations/2026-10-26-breach-doctor.sql). Done when the metric reads 0 and stays 0 for 3 ticks.',
  'qnfo-fleet-control', 'agent_issues', 2, 1, 'BREACH-DOCTOR-1 (migrations/2026-10-26-breach-doctor.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = 'breaches_undiagnosed_over_60m');

INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'breaches_auto_remediated_24h', 'The doctor verified fewer than 12 remediations in 24 hours', 'registry', 'lt', 12, 2,
  'Pillar autonomy. Read: SELECT family, cause_class, state, COUNT(*) FROM v_breach_diagnosis_current GROUP BY 1, 2, 3 ORDER BY 4 DESC; SELECT * FROM v_breach_doctor_status. The lever is a playbook, not code: for the largest family with cause_class unclassified (SELECT unclassified_cases, gap_by_family FROM v_breach_doctor_status; the doctor files no gap issue while playbook-gap is in measure), add a breach_playbooks row by migration (trigger_sql returns issue_id, subject, facts_json; action_sql and revert_sql statements bind ?1; verify_sql returns expected and observed), see migrations/2026-10-26-breach-doctor.sql for the shape; a new row runs in measure for 30 minutes. Done when the metric reads 12 or more.',
  'qnfo-fleet-control', 'agent_issues', 2, 1, 'BREACH-DOCTOR-1 (migrations/2026-10-26-breach-doctor.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = 'breaches_auto_remediated_24h');

INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'doctor_actions_failed_24h', 'A doctor action failed or was reverted', 'registry', 'gt', 0, 1,
  'Pillar autonomy. Read: SELECT id, issue_id, rule_id, state, error_code, attempts FROM breach_diagnoses WHERE state IN (''failed'', ''reverted'') ORDER BY id DESC LIMIT 20; SELECT event, detail FROM breach_diagnosis_events WHERE event IN (''fail'', ''demote'') ORDER BY id DESC LIMIT 20. A rule with 2 failures in 24 hours has demoted itself to measure. Lever: fix the playbook row named by rule_id by migration (its action_sql guard, its verify_sql) or the engine step named by error_code (sql-error, no-rows, verify-failed, verify-error, lease-expired). Done when no case failed in 24 hours.',
  'qnfo-fleet-control', 'agent_issues', 2, 1, 'BREACH-DOCTOR-1 (migrations/2026-10-26-breach-doctor.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = 'doctor_actions_failed_24h');

INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'doctor_tick_age_min', 'The breach doctor has not ticked in 30 minutes', 'registry', 'gt', 30, 1,
  'Pillar autonomy. Read: SELECT MAX(ts) FROM breach_diagnosis_events WHERE event = ''tick''; SELECT * FROM v_breach_doctor_status; SELECT k, holder, expires_at FROM loop_lock WHERE k = ''breach-doctor''. Causes: ops_config breach_doctor = off, a loop_lock row that never expires, the */10 slot of qnfo-fleet-control not reaching the doctor (a thrown step before it), or a missing table after a failed migration. Lever: the call site in scheduledOnce and the tick itself. Done when a tick event is under 15 minutes old.',
  'qnfo-fleet-control', 'agent_issues', 2, 1, 'BREACH-DOCTOR-1 (migrations/2026-10-26-breach-doctor.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = 'doctor_tick_age_min');

INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'doctor_taint_violations_24h', 'A doctor playbook or fact carried free text', 'registry', 'gt', 0, 1,
  'Pillar security (the taint rule: free text never flows into an issue, a probe, a task or a prompt). Read: SELECT ts, detail FROM breach_diagnosis_events WHERE event = ''taint-drop'' ORDER BY id DESC LIMIT 20; the detail names the rule and the reason code (free-text-column, forbidden-keyword, semicolon, not-insert-or-update, table-not-allowed, no-issue-param, bad-json, fact-value). Lever: fix the named breach_playbooks row by migration so its statements name no description, exceptions_json or cloud_ops_events text column and its facts_json holds only numbers, ids and enum codes. Done when no taint-drop event is 24 hours old.',
  'qnfo-fleet-control', 'agent_issues', 2, 1, 'BREACH-DOCTOR-1 (migrations/2026-10-26-breach-doctor.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = 'doctor_taint_violations_24h');

-- OWNER-NO-LOOSE-ENDS-1 / ANTIFRAGILE-1 (review 2026-10-26): the three follow-ups this file leaves are agent_issues rows with a named doer and a closing probe, not prose.
-- Source 'session' is on ops_config code_merge_trusted_sources (live list read 2026-10-26), so each row is plannable; none carries a code-task line except BREACH-DOCTOR-WATCHMAKER-1, whose lever is one named
-- edit in one file (ACT-BRIDGE-1). Each row's contract is born by the issue-birth trigger as needs-machine-probe in D1; the INSERT OR IGNORE below only gives a replay (and the offline suite) the same row,
-- and the UPDATE sets the probe the hourly remediation tick runs. No probe reads true today.
INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'BREACH-DOCTOR-WATCH-1: the breach doctor has one runner, so qnfo-cloud-ops gets a watch that acts when the doctor stops ticking',
  'Charter pillar: autonomy. spof_registry holds "breach doctor tick (qnfo-fleet-control */10)": one cron slot and one runner on the path from an unowned breach to a verified close. ANTIFRAGILE-1: a design with one executor on a critical path ships with its second path or an issue that builds it; this is that issue.' || char(10) ||
  'Doer: a session (a design, not a single-file edit, so no code-task line). Change in qnfo-cloud-ops/worker.js, on the existing hourly tick and CRON_TABLE (CRON-SINGLE-TRIGGER-1, no new cron): jobBreachDoctorWatch reads the newest breach_diagnosis_events tick; when it is older than 30 minutes (doctor_tick_age_min) it runs the same validated per-issue playbooks (the S1 validators) and records every action in breach_diagnoses; every run, acting or not, logs a job-run event for job breach-doctor-watch (a heartbeat, the lesson of PARK-REARM-HEARTBEAT-1). Then set spof_registry alternate_tested_at and control_registry breach-doctor-switch alternate_tested_at in the same migration.' || char(10) ||
  'Definition of done: a cloud_ops_events job-run row for job breach-doctor-watch is under 120 minutes old (the closing probe of this issue) and the spof_registry row names the tested alternate.',
  'session', 'autonomy', 'high', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCH-1:%');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'BREACH-DOCTOR-WATCHMAKER-1: WATCHMAKER_OPS has no entry for the breach doctor tick',
  'Charter pillar: autonomy. NO-CLAUDE-RUNTIME-DEPENDENCY-1: a PR that adds a recurring operation adds it to WATCHMAKER_OPS in qnfo-fleet-dashboard/worker.js with the D1 query that proves it ran. BREACH-DOCTOR-1 adds the doctor tick on the qnfo-fleet-control */10 slot and the spec for that package left the dashboard alone, so the entry is missing and watchmaker_index cannot see a stalled doctor.' || char(10) ||
  'Doer: the code loop (one edit in one file). Change: add one entry to the WATCHMAKER_OPS array: key breach-doctor, what "Diagnosis and remediation of unowned breaches (BREACH-DOCTOR-1, qnfo-fleet-control, every 10 minutes)", runner cron:qnfo-fleet-control, cadence_h 1, first_due 2026-10-27T00:00:00Z, sql SELECT MAX(ts) AS last FROM breach_diagnosis_events WHERE event = ''tick''.' || char(10) ||
  'Definition of done: qnfo-fleet-dashboard/worker.js on main holds the WATCHMAKER_OPS entry with key "breach-doctor" (a Diagnose panel that merely reads breach_diagnosis_events does not count) and the canonical deploy of qnfo-fleet-dashboard is live.' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-dashboard/worker.js' || char(10) ||
  'code-anchor: var WATCHMAKER_OPS = [' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-dashboard/worker.js"], "contains": "key: \"breach-doctor\""}',
  'session', 'autonomy', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCHMAKER-1:%');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'BREACH-DOCTOR-RETIRE-1: retire the two older writers the doctor replaces (deploy_merge_age_tick and breach_selfheal_heavy_tick)',
  'Charter pillar: autonomy. Net-zero rule: BREACH-DOCTOR-1 adds three table families (breach_diagnoses, breach_diagnosis_events, breach_playbooks) and funds the retirement of the same class. Read from live qnfo-audit sqlite_master 2026-10-26: the only writers of issue_age_replans and breach_selfheal_actions are the D1 triggers deploy_merge_age_tick (on fleet_tick) and breach_selfheal_heavy_tick (on fleet_tick_heavy); both tables stay readable.' || char(10) ||
  'Doer: a session, after the doctor has a verified case (breaches_auto_remediated_24h above 0) and after the second path of BREACH-DOCTOR-WATCH-1 exists. Change: one migration with APPLY-BY ci, DB qnfo-audit, a Rollback line that recreates both triggers from their stored text, and a BACKUP table it creates first that holds the two trigger definitions; run /fleet-graph/impact on d1trg:qnfo-audit.deploy_merge_age_tick and d1trg:qnfo-audit.breach_selfheal_heavy_tick first and cover what it returns in the same change (DEPLOY-ALL-MERGES-1 reads issue_age_replans).' || char(10) ||
  'Definition of done: neither trigger is installed in qnfo-audit (the closing probe of this issue) and the replacement for each duty is named in the migration.',
  'session', 'autonomy', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-RETIRE-1:%');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id, id, 'born with the issue (ORPHAN-GUARD-BIRTH-1)', 'needs-machine-probe', 'needs-machine-probe', 'd1-query', 3, 'qnfo-fleet-control', 1, 'needs-machine-probe', 'birth'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCH-1:%' OR title LIKE 'BREACH-DOCTOR-WATCHMAKER-1:%' OR title LIKE 'BREACH-DOCTOR-RETIRE-1:%';

UPDATE remediation_contracts SET precondition = 'BREACH-DOCTOR-1: the doctor tick is the only runner of the diagnosis path',
  action = 'a session adds jobBreachDoctorWatch to qnfo-cloud-ops; the stale-PR lane merges it and the canonical deploy ships it',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''job-run'' AND job = ''breach-doctor-watch'' AND ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-120 minutes'')) THEN ''no breach-doctor-watch job-run event in the last 120 minutes'' ELSE ''ok'' END AS observed',
  verify_transport = 'd1-query', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'breach-doctor'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCH-1:%' ORDER BY id DESC LIMIT 1);

UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main; scripts/remediation_consumer.py reads its checkout of main and a pass closes the issue',
  verify_probe = '{"paths": ["qnfo-fleet-dashboard/worker.js"], "contains": "key: \"breach-doctor\""}',
  verify_transport = 'code-read', max_attempts = 3, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCHMAKER-1:%' ORDER BY id DESC LIMIT 1);

UPDATE remediation_contracts SET precondition = 'BREACH-DOCTOR-1: two older writers stay installed until the doctor has proved its replacement',
  action = 'a session writes the retirement migration after the impact check; the stale-PR lane merges it and CI applies it',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM sqlite_master WHERE type = ''trigger'' AND name IN (''deploy_merge_age_tick'', ''breach_selfheal_heavy_tick'')) THEN ''still installed: '' || (SELECT group_concat(name) FROM sqlite_master WHERE type = ''trigger'' AND name IN (''deploy_merge_age_tick'', ''breach_selfheal_heavy_tick'')) ELSE ''ok'' END AS observed',
  verify_transport = 'd1-query', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'breach-doctor'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-RETIRE-1:%' ORDER BY id DESC LIMIT 1);

